INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'fiche', 1, NULL, 'Parade/Esquive illimité', 'fiche', 'Fiche auto V15.2.2 › Personnage › BR18 (ligne 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'fiche', 2, NULL, '+2/4 niveau global AP/AM', 'fiche', 'Fiche auto V15.2.2 › Personnage › BR18 (ligne 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'fiche', 3, NULL, 'Intervention', 'fiche', 'Fiche auto V15.2.2 › Personnage › BR18 (ligne 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'fiche', 4, NULL, 'Provocation', 'fiche', 'Fiche auto V15.2.2 › Personnage › BR18 (ligne 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'fiche', 5, NULL, '+5% à la RC à la défense', 'fiche', 'Fiche auto V15.2.2 › Personnage › BR18 (ligne 5)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'fiche', 6, NULL, 'Divise par 2 les dégâts infligés (division AVANT l''armure)', 'fiche', 'Fiche auto V15.2.2 › Personnage › BR18 (ligne 6)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'guide_fiche', 1, '+2AP/AM', 'L’armure physique et magique augmente quand cette posture est prise. Cela augmente de +2 tous les 4 niveaux global du personnage.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Défensif (puce 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'guide_fiche', 2, 'Parade/Esquive illimité', 'Permet d''esquiver ou de parer tous les coups dans un tour MAIS chaque coup va diminuer la réussite de la prochaine parade/esquive de 10%.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Défensif (puce 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'guide_fiche', 3, 'Provocation', 'Permet en échange d''un bon dialogue et d''un jet de diplomatie, intimidation ou manipulation réussi, d''obliger un adversaire à venir vous attaquer que vous pendant 1 tour.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Défensif (puce 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'guide_fiche', 4, 'Intervention', 'Permet de parer/esquiver le coup à la place d''un allié adjacent.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Défensif (puce 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'guide_fiche', 5, '+5% à la réussite critique avec une défense', 'La réussite critique (ou coup critique) est de base à 5 ou moins, grâce à la posture défensive, cette réussite critique monte à 10 ou moins quand on esquive ou pare une attaque.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Défensif (puce 5)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'guide_fiche', 6, 'Divise les dégâts par 2 infligés', 'Armes ou Magie, les dégâts infligés seront divisés par 2, cette division intervient AVANT le calcule de l’armure.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Défensif (puce 6)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'guide_mj', 1, '+2AP/AM', 'L’armure physique et magique augmente quand cette posture est prise. Cela augmente de +2 tous les 4 niveaux global du personnage.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Défensif (puce 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'guide_mj', 2, 'Parade/Esquive illimité', 'Permet d''esquiver ou de parer tous les coups dans un tour MAIS dès que le nombre de parade/esquive est au delà de deux = chaque coup va diminuer la réussite de la prochaine parade/esquive de 10%.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Défensif (puce 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'guide_mj', 3, 'Provocation', 'Permet en échange d''un bon dialogue ou d''un jet de diplomatie, intimidation ou manipulation réussi, d''obliger un adversaire à venir vous attaquer que vous pendant 1 tour.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Défensif (puce 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'guide_mj', 4, 'Intervention', 'Permet de parer/esquiver le coup à la place d''un allié adjacent.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Défensif (puce 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'guide_mj', 5, '+5% à la réussite critique avec une défense', 'La réussite critique (ou coup critique) est de base à 5 ou moins, grâce à la posture défensive, cette réussite critique monte à 10 ou moins quand on esquive ou pare une attaque.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Défensif (puce 5)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:defensif', 'guide_mj', 6, 'Divise les dégâts par 2 infligés', 'Armes ou Magie, les dégâts infligés seront divisés par 2, cette division intervient AVANT le calcule de l’armure.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Défensif (puce 6)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:focus', 'fiche', 1, NULL, '+10% à la réussite', 'fiche', 'Fiche auto V15.2.2 › Personnage › BA25 (ligne 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:focus', 'fiche', 2, NULL, 'Augmente la valeur des dés de dégâts/soin des sortilèges', 'fiche', 'Fiche auto V15.2.2 › Personnage › BA25 (ligne 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:focus', 'fiche', 3, NULL, '-1 tour de charge', 'fiche', 'Fiche auto V15.2.2 › Personnage › BA25 (ligne 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:focus', 'fiche', 4, NULL, 'Esquive/Parade impossible', 'fiche', 'Fiche auto V15.2.2 › Personnage › BA25 (ligne 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:focus', 'guide_fiche', 1, '+10% à la réussite', 'Peut importe le type de jet, il bénéficie d’un bonus de 10% à la réussite.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Focus (puce 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:focus', 'guide_fiche', 2, '-1 tour de charge', 'Permet de retirer le tour de charge des sorts de niveau 5 de puissance et de retirer le tour de charge lors de certaines actions. Casse le tour de charge de la capacité "Préparation" du Mage Rouge et Vert.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Focus (puce 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:focus', 'guide_fiche', 3, 'Augmente le cran de dé de dégâts/soin', 'Permet d’augmenter d’un cran la nature des dés qui seront lancés pour le sortilège (le D6 devient D8, etc…en sachant qu’il n’y pas plus haut que le D20)', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Focus (puce 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:focus', 'guide_fiche', 4, 'Esquive/Parade impossible', 'Pas besoin d''expliquer, la posture vous empêche d''esquiver ou de parer une agression ennemie.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Focus (puce 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:focus', 'guide_mj', 1, '+10% à la réussite', 'Peut importe le type de jet, il bénéficie d’un bonus de 10% à la réussite.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Focus (puce 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:focus', 'guide_mj', 2, '-1 tour de charge', 'Permet de retirer le tour de charge des sorts de niveau 5 de puissance et de retirer le tour de charge lors de certaines actions. Casse le tour de charge de la capacité "Préparation" du Mage Rouge et Vert.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Focus (puce 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:focus', 'guide_mj', 3, 'Augmente le cran de dé de dégâts/soin', 'Permet d’augmenter d’un cran la nature des dés qui seront lancés pour le sortilèges (le D6 devient D8, etc…en sachant qu’il n’y pas plus haut que le D20)', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Focus (puce 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:focus', 'guide_mj', 4, 'Esquive/Parade impossible', 'Pas besoin d''expliquer, la posture vous empêche d''esquiver ou de parer une agression ennemie.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Focus (puce 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:neutre', 'fiche', 1, NULL, '+5% pour jet de V ou S', 'fiche', 'Fiche auto V15.2.2 › Personnage › BI18 (ligne 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:neutre', 'fiche', 2, NULL, '2 esquive/parade par tour', 'fiche', 'Fiche auto V15.2.2 › Personnage › BI18 (ligne 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:neutre', 'guide_fiche', 1, '+5% pour un jet V ou S', 'Permet d''avoir un bonus de 5% à tout jet impliquant la caractéristique Social ou Volonté.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Neutre (puce 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:neutre', 'guide_fiche', 2, '2 esquive/parade par tour', 'Permet d''esquiver ou de parer deux fois par tour.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Neutre (puce 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:neutre', 'guide_mj', 1, '+5% pour un jet V ou S', 'Permet d''avoir un bonus de 5% à tout jet impliquant la caractéristique Social ou Volonté.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Neutre (puce 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:neutre', 'guide_mj', 2, '2 esquive/parade par tour', 'Permet d''esquiver ou de parer deux fois par tour.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Neutre (puce 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:offensif', 'fiche', 1, NULL, 'Dégâts maximum', 'fiche', 'Fiche auto V15.2.2 › Personnage › BA18 (ligne 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:offensif', 'fiche', 2, NULL, '+5% à la réussite critique', 'fiche', 'Fiche auto V15.2.2 › Personnage › BA18 (ligne 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:offensif', 'fiche', 3, NULL, 'Malus de 10% pour toucher une cible', 'fiche', 'Fiche auto V15.2.2 › Personnage › BA18 (ligne 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:offensif', 'fiche', 4, NULL, 'Esquive/Parade impossible', 'fiche', 'Fiche auto V15.2.2 › Personnage › BA18 (ligne 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:offensif', 'guide_fiche', 1, 'Dégâts maximum', 'Armes ou Magie, les dégâts seront au minimum avec les bonus. [Exemple : 2d6+2 de dégâts en offensif fera automatiquement 14 dégâts, les jets de dés ne sont pas a faire vu que c''est le maximum que l''on prend]', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Offensif (puce 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:offensif', 'guide_fiche', 2, '+5% à la réussite critique', 'La réussite critique (ou coup critique) est de bas à 5 ou moins, grâce à la posture offensif, cette réussite critique monte à 10 ou moins.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Offensif (puce 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:offensif', 'guide_fiche', 3, 'Malus de 10% pour toucher une cible', 'La posture diminue la chance que vous avez de toucher votre cible.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Offensif (puce 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:offensif', 'guide_fiche', 4, 'Esquive/Parade impossible', 'Pas besoin d''expliquer, la posture vous empêche d''esquiver ou de parer une agression ennemie.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Offensif (puce 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:offensif', 'guide_mj', 1, 'Dégâts maximum', 'Armes ou Magie, les dégâts seront au minimum avec les bonus. [Exemple : 2d6+2 de dégâts en offensif fera automatiquement 14 dégâts, les jets de dés ne sont pas a faire vu que c''est le maximum que l''on prend]', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Offensif (puce 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:offensif', 'guide_mj', 2, '+5% à la réussite critique', 'La réussite critique (ou coup critique) est de base à 5 ou moins, grâce à la posture offensif, cette réussite critique monte à 10 ou moins.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Offensif (puce 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:offensif', 'guide_mj', 3, 'Malus de 10% pour toucher une cible', 'La posture diminue la chance que vous avez de toucher votre cible.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Offensif (puce 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:offensif', 'guide_mj', 4, 'Esquive/Parade impossible', 'Pas besoin d''expliquer, la posture vous empêche d''esquiver ou de parer une agression ennemie.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Offensif (puce 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'fiche', 1, NULL, '+5 (+2/NPM) dégâts/soin avec une magie', 'fiche', 'Fiche auto V15.2.2 › Personnage › BR25 (ligne 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'fiche', 2, NULL, '+4 (+2/NPM) à l''Armure magique', 'fiche', 'Fiche auto V15.2.2 › Personnage › BR25 (ligne 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'fiche', 3, NULL, 'Immunité à la magie de la symbiose', 'fiche', 'Fiche auto V15.2.2 › Personnage › BR25 (ligne 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'fiche', 4, NULL, 'Impossible d''utiliser les armes ou objets', 'fiche', 'Fiche auto V15.2.2 › Personnage › BR25 (ligne 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'fiche', 5, NULL, '1 seule parade/esquive par tour', 'fiche', 'Fiche auto V15.2.2 › Personnage › BR25 (ligne 5)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'fiche', 6, NULL, 'Une seule magie active', 'fiche', 'Fiche auto V15.2.2 › Personnage › BR25 (ligne 6)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_fiche', 1, '+5 dégâts/soin avec une magie', 'Permet d''infliger un bonus de dégâts de +6 ou alors un bonus de +5 avec un sort de soin. Cela augmente de +2 tous les niveaux de puissance magique (le premier niveau ne compte pas)', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Symbiose (puce 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_fiche', 2, '+4 AM', 'Permet d''avoir une plus grande armure magique dans cette posture. Cela augmente de +2 tous les niveaux de puissance magique (le premier niveau ne compte pas)', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Symbiose (puce 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_fiche', 3, 'Immunité à la magie de la symbiose', 'La magie avec laquelle vous avez fait la symbiose vous envahit et vous devenez totalement immunisé à celle ci.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Symbiose (puce 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_fiche', 4, 'Une seule parade/esquive par tour', 'Permet d''esquiver ou de parer une fois par tour.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Symbiose (puce 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_fiche', 5, 'Impossible d''utiliser les objets et armes (sauf forgemagie)', 'Vous êtes quasiment un élémentaire, les armes physiques et les objets ne sont pas dans votre optique (la forgemagie est un sort qui permet de créer des armes faites de magie, donc c''est bon)', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Symbiose (puce 5)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_fiche', 6, 'Une seule magie active', 'Quand vous avez 2 magies, 1 de ses magies doit être désactiver temporairement, ainsi tout ses avantages et inconvénients sont annulés également.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Symbiose (puce 6)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_mj', 1, '+5 dégâts/soin avec une magie', 'Permet d''infliger un bonus de dégâts de +5 ou alors un bonus de +5 avec un sort de soin. Cela augmente de +2 tous les niveaux de puissance magique (le premier niveau ne compte pas)', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Symbiose (puce 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_mj', 2, '+4 AM', 'Permet d''avoir une plus grande armure magique dans cette posture. Cela augmente de +2 tous les niveaux de puissance magique (le premier niveau ne compte pas)', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Symbiose (puce 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_mj', 3, 'Immunité à la magie de la symbiose', 'La magie avec laquelle vous avez fait la symbiose vous envahit et vous devenez totalement immunisé à celle ci.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Symbiose (puce 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_mj', 4, '+1 tour d''effet pour les effets secondaires avec des tours', 'Si votre sortilège possède un effet qui dure sur plusieurs tours, la posture permet d''ajouter 1 tour gratuitement.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Symbiose (puce 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_mj', 5, 'Une seule parade/esquive par tour', 'Permet d''esquiver ou de parer une fois par tour.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Symbiose (puce 5)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_mj', 6, 'Impossible d''utiliser les objets et armes (sauf forgemagie)', 'Vous êtes quasiment un élémentaire, les armes physiques et les objets ne sont pas dans votre optique (“Forgemagie”, “Forge de ses morts”, Bâton magique et les parchemins ne sont pas interdit)', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Symbiose (puce 6)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:symbiose', 'guide_mj', 7, 'Une seule magie active', 'Quand vous avez 2 magies, 1 de ses magies doit être désactiver temporairement, ainsi tout ses avantages et inconvénients sont annulés également.', 'fiche', 'Google Doc « Règle du jeu/Guide pour MJ - Maverick » › Postures › Symbiose (puce 7)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:vigilance', 'fiche', 1, NULL, '+5% jet de perception', 'fiche', 'Fiche auto V15.2.2 › Personnage › BI25 (ligne 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:vigilance', 'fiche', 2, NULL, '+2 initiative', 'fiche', 'Fiche auto V15.2.2 › Personnage › BI25 (ligne 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:vigilance', 'fiche', 3, NULL, 'Peut anticipé les actions adverse en IC', 'fiche', 'Fiche auto V15.2.2 › Personnage › BI25 (ligne 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:vigilance', 'fiche', 4, NULL, 'Repérer un ennemi invisible devient un IC', 'fiche', 'Fiche auto V15.2.2 › Personnage › BI25 (ligne 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:vigilance', 'fiche', 5, NULL, 'Peut repérer 1d4 résistance/vulnérabilité d''un ennemi  en IC', 'fiche', 'Fiche auto V15.2.2 › Personnage › BI25 (ligne 5)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:vigilance', 'fiche', 6, NULL, '1 seule parade/esquive par tour', 'fiche', 'Fiche auto V15.2.2 › Personnage › BI25 (ligne 6)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:vigilance', 'guide_fiche', 1, '+5% pour un jet de Perception', 'Permet d''avoir un bonus de 5% à tout jet impliquant la caractéristique Perception.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Vigilance (puce 1)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:vigilance', 'guide_fiche', 2, '+2 Initiative', 'Permet d''avoir un bonus d''initiative de +2 lors du début de chaque tour.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Vigilance (puce 2)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:vigilance', 'guide_fiche', 3, 'Peut anticiper les actions adverses', 'Permet grâce un jet d''observation/distinction d''avoir une info intéressante sur la prochaine action de l''adversaire, voir le mj pour ça.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Vigilance (puce 3)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:vigilance', 'guide_fiche', 4, 'Repérer un adversaire invisible devient un IC', 'Permet à l’action “estimer la position d’un ennemi invisible ou discret” de devenir un IC.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Vigilance (puce 4)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:vigilance', 'guide_fiche', 5, 'Peut repérer 1d4 résistance/vulnérabilité', 'Permet d’utiliser un IC pour détecter une résistance ou vulnérabilité aléatoire de l’ennemi.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Vigilance (puce 5)');
INSERT INTO posture_effet (posture_id, version, rang, intitule, texte, origine, source_ref) VALUES ('guide/postures#posture:vigilance', 'guide_fiche', 6, 'Une seule parade/esquive par tour', 'Permet d''esquiver ou de parer une fois par tour.', 'fiche', 'Google Doc « Créer sa fiche de personnage » › Tableau Posture › Vigilance (puce 6)');
